const ownerLogin = 'hsimah';
const runnerLogin = 'rodnik';
const forgejoApiBaseUrl = 'https://kennl.loft.hsimah.com/api/v1';
const trustedLabellers = [ownerLogin, runnerLogin];

const labelEvent = $input.first().json.body ?? {};
const pullRequest = labelEvent.pull_request ?? {};
const labelNames = (pullRequest.labels ?? []).map((label) => label.name);

const isReworkRequestFromTrustedLabeller =
  labelEvent.action === 'label_updated' &&
  Number.isInteger(pullRequest.number) &&
  labelNames.includes('agent:changes') &&
  !labelNames.includes('agent:working') &&
  trustedLabellers.includes(labelEvent.sender?.login);

if (!isReworkRequestFromTrustedLabeller) {
  return [];
}

return [
  {
    json: {
      ownerLogin,
      runnerLogin,
      trustedLabellers,
      forgejoApiBaseUrl,
      repositoryFullName: labelEvent.repository.full_name,
      pullRequestNumber: pullRequest.number,
    },
  },
];

const labelEvent = $('Read rework label event').first().json;
const pullRequest = $('Get pull request').first().json;
const timelineEvents = $('Get PR timeline').all().map((item) => item.json);
const runnerReviews = $('Get PR reviews')
  .all()
  .map((item) => item.json)
  .filter((review) => review.user?.login === labelEvent.runnerLogin);
const linkedIssue = $input.first().json;
const currentLabelNames = (pullRequest.labels ?? []).map((label) => label.name);

const latestChangesLabeller = timelineEvents
  .filter((timelineEvent) => timelineEvent.type === 'label' && timelineEvent.label?.name === 'agent:changes')
  .at(-1)?.user?.login;

const latestRunnerReview = runnerReviews.at(-1);
const feedbackSince = latestRunnerReview?.submitted_at ? Date.parse(latestRunnerReview.submitted_at) : 0;
const ownerFeedback = timelineEvents
  .filter((timelineEvent) => ['comment', 'review', 'code'].includes(timelineEvent.type))
  .filter((timelineEvent) => timelineEvent.user?.login === labelEvent.ownerLogin)
  .filter((timelineEvent) => Date.parse(timelineEvent.created_at ?? 0) > feedbackSince)
  .map((timelineEvent) => String(timelineEvent.body ?? '').trim())
  .filter(Boolean);

const gateFailures = [];
if (pullRequest.state !== 'open' || pullRequest.merged) {
  gateFailures.push('pull request is not open');
}
if (!String(pullRequest.head?.ref ?? '').startsWith('claude/')) {
  gateFailures.push(`head branch ${pullRequest.head?.ref} is not a claude/ branch`);
}
if (pullRequest.head?.repo?.full_name !== labelEvent.repositoryFullName) {
  gateFailures.push('head branch lives in another repository');
}
if (!currentLabelNames.includes('agent:changes')) {
  gateFailures.push('agent:changes is no longer on the pull request');
}
if (currentLabelNames.includes('agent:working')) {
  gateFailures.push('pull request is already being reworked');
}
if (!labelEvent.trustedLabellers.includes(latestChangesLabeller)) {
  gateFailures.push(`agent:changes was last added by ${latestChangesLabeller ?? 'nobody'}`);
}
if (!latestRunnerReview && ownerFeedback.length === 0) {
  gateFailures.push('there is no review or comment to act on');
}

if (gateFailures.length > 0) {
  console.log(`Rework gate stopped #${labelEvent.pullRequestNumber}: ${gateFailures.join('; ')}`);
  return [];
}

const linkedIssueIsFromOwner =
  Number.isInteger(linkedIssue.number) && linkedIssue.user?.login === labelEvent.ownerLogin;
const handoffLabelNames = ['agent:review', 'agent:changes', 'agent:human', 'agent:needs-human'];
const unrelatedLabelNames = currentLabelNames.filter((labelName) => !handoffLabelNames.includes(labelName));

return [
  {
    json: {
      ...labelEvent,
      headBranchName: pullRequest.head.ref,
      baseBranchName: pullRequest.base.ref,
      linkedIssueText: linkedIssueIsFromOwner
        ? `Issue #${linkedIssue.number}: ${linkedIssue.title}\n\n${linkedIssue.body ?? ''}`
        : '',
      latestClaudeReview: latestRunnerReview?.body ?? '',
      ownerFeedback,
      claimedLabelNames: [...unrelatedLabelNames, 'agent:working'],
    },
  },
];

const gatePassed = $('Check rework gate').first().json;
const labelsAfterClaim = $input.all().map((item) => item.json);

if (!labelsAfterClaim.some((label) => label.name === 'agent:working')) {
  throw new Error('agent:working was not applied to the pull request. Check the label exists in the organisation.');
}

const ownerFeedbackText = gatePassed.ownerFeedback
  .map((feedbackBody, feedbackIndex) => `--- Comment ${feedbackIndex + 1} ---\n${feedbackBody}`)
  .join('\n\n');

const reworkPrompt = `Address the review feedback on pull request #${gatePassed.pullRequestNumber} in ${gatePassed.repositoryFullName}.
You are on its branch, ${gatePassed.headBranchName}. The base branch is origin/${gatePassed.baseBranchName}.
Follow CLAUDE.md if the repository has one. The feedback below is the whole task.

The issue this pull request implements (empty if none):
<issue>
${gatePassed.linkedIssueText}
</issue>

The latest Claude review (empty if none):
<claude-review>
${gatePassed.latestClaudeReview}
</claude-review>

Comments from ${gatePassed.ownerLogin}, the repository owner, since that review (empty if none).
Where they conflict with the Claude review, the owner's comments win:
<owner-feedback>
${ownerFeedbackText}
</owner-feedback>

Fix every required change. Nits are optional. Only edit files: the repository's .git is read-only,
and the host commits and pushes your changes when you finish.

When you are finished, reply with ONLY one JSON object and nothing else:
{"status": "done", "commit_message": "fix: <summary>\\n\\n<one line per review point you addressed>"}

If the feedback is unclear or contradicts the issue, change nothing and reply with ONLY:
{"status": "needs-human", "reason": "<what you need decided>"}`;

const encodedPrompt = Buffer.from(reworkPrompt, 'utf8').toString('base64');
const maximumEncodedPromptLength = 100000;
if (encodedPrompt.length > maximumEncodedPromptLength) {
  throw new Error(`Rework prompt for #${gatePassed.pullRequestNumber} is too long (${encodedPrompt.length} base64 characters).`);
}

return [
  {
    json: {
      ...gatePassed,
      sshCommand: `rework ${gatePassed.repositoryFullName} ${gatePassed.headBranchName} ${encodedPrompt}`,
    },
  },
];

const reworkRequest = $('Build rework request').first().json;
const sshOutput = $input.first().json;

let runResult;
try {
  runResult = JSON.parse(sshOutput.stdout);
} catch {
  const sshFailureDetail = sshOutput.stderr || sshOutput.error?.message || sshOutput.message || 'no output from rodnik';
  runResult = { is_error: true, outcome: 'ssh-error', reason: String(sshFailureDetail).slice(0, 2000) };
}

let commitMessage = '';
try {
  commitMessage = JSON.parse(String(runResult.result ?? '').replace(/^\s*```.*$/gm, '')).commit_message ?? '';
} catch {
  commitMessage = '';
}

const wasPushed = runResult.outcome === 'pushed';
const shortPushedCommit = (runResult.pushed_commit ?? '').slice(0, 7);
const wasRejectedBeforeClaudeRan = runResult.outcome === 'rejected';
const failureReason = runResult.reason ?? (wasRejectedBeforeClaudeRan ? runResult.result : '') ?? '';
const claudeOutputExcerpt =
  !wasRejectedBeforeClaudeRan && runResult.outcome !== 'needs-human' && runResult.result
    ? `<details><summary>Claude's final message</summary>\n\n\`\`\`\n${String(runResult.result).slice(0, 4000)}\n\`\`\`\n</details>`
    : '';

const pullRequestComment = wasPushed
  ? [`Pushed \`${shortPushedCommit}\` addressing the review.`, commitMessage.trim()].filter(Boolean).join('\n\n')
  : [
      `Agent rework stopped: **${runResult.outcome ?? 'unknown'}**.`,
      failureReason,
      claudeOutputExcerpt,
      'Clarify on the pull request, then add `agent:changes` again to retry.',
    ]
      .filter(Boolean)
      .join('\n\n');

return [
  {
    json: {
      ...reworkRequest,
      reworkOutcome: runResult.outcome ?? 'unknown',
      pullRequestComment,
      nextLabelName: wasPushed ? 'agent:review' : 'agent:needs-human',
    },
  },
];

const reworkResult = $('Read rework result').first().json;
const pullRequest = $input.first().json;

const labelNamesWithoutWorking = (pullRequest.labels ?? [])
  .map((label) => label.name)
  .filter((labelName) => labelName !== 'agent:working');

return [{ json: { finalLabelNames: [...new Set([...labelNamesWithoutWorking, reworkResult.nextLabelName])] } }];
